<script lang="ts">
  import type { BacktestController } from '../state/backtest.svelte';
  import { date, duration, euro, number, percent, relativeUpdatedAt, updatedAt } from '../services/formatters';
  import LineChart from './LineChart.svelte';
  let { controller }: { controller: BacktestController } = $props();
  const periods = { '1m': { label: '1M', description: '1 month' }, '3m': { label: '3M', description: '3 months' }, '6m': { label: '6M', description: '6 months' }, '1y': { label: '1Y', description: '1 year' }, '2y': { label: '2Y', description: '2 years' }, '5y': { label: '5Y', description: '5 years' } } as const;
  let period = $derived(controller.direction === 'backward' ? controller.backwardPeriod : controller.forwardPeriod);
  let benchmarkUsesReyndersTax = $derived(controller.view?.settings.applyReyndersTax ?? controller.settings.applyReyndersTax);
  let selectedSeries = $derived(controller.benchmark?.[controller.benchmarkAfterTax ? benchmarkUsesReyndersTax ? 'reynders' : 'cgt' : 'gross']?.[controller.direction === 'backward' ? 'lookback' : 'forward']?.[period as '1y']);
</script>
<section id="results" aria-live="polite">
{#if controller.view}
  {@const result = controller.view.result}
  {@const settings = controller.view.settings}
  {@const negative = result.missedAmount < 0}
  {@const csh2UpdatedAt = new Date(controller.view.metadata.cachedAt)}
  {@const estrUpdatedAt = controller.view.rateMetadata.cachedAt ? new Date(controller.view.rateMetadata.cachedAt) : undefined}
    <div class="result-heading"><div><p class="eyebrow">As of {result.valuation.date}</p><h2>Backtest result</h2></div><p class="source"><span class="timestamp-wrapper"><button type="button" class="timestamp" aria-describedby="csh2-update-tooltip">CSH2 data last updated {relativeUpdatedAt(csh2UpdatedAt)}</button><span id="csh2-update-tooltip" class="timestamp-tooltip" role="tooltip">{updatedAt.format(csh2UpdatedAt)}</span></span><br />{#if estrUpdatedAt}<span class="timestamp-wrapper"><button type="button" class="timestamp" aria-describedby="estr-update-tooltip">€STR data last updated {relativeUpdatedAt(estrUpdatedAt)}</button><span id="estr-update-tooltip" class="timestamp-tooltip" role="tooltip">{updatedAt.format(estrUpdatedAt)}</span></span>{:else}<span>€STR data last updated unavailable</span>{/if}</p></div>
    <div class="metrics">
      <article class:negative class="metric main missed-result"><p>{negative ? 'CSH2 would currently be below your account balance by' : 'You missed out on'}</p><strong>{euro.format(Math.abs(result.missedAmount))}</strong><small>{result.missedSharePercent === undefined ? 'Your account balance is zero.' : negative ? `a shortfall equal to ${percent(Math.abs(result.missedSharePercent))}% of your account balance, including interest` : `which is ${percent(result.missedSharePercent)}% of your account balance, including interest`}</small>
        {#if negative && result.breakEvenEstimate}<small>Estimated break-even in <b>{duration(result.valuation.date, result.breakEvenEstimate.date)}</b></small><small>(assuming the CSH2 price keeps its {result.breakEvenEstimate.trendDays}-day trend of {percent(result.breakEvenEstimate.trendReturnPercent)}%)</small>{:else if negative}<small>Break-even can’t be estimated from the recent price trend.</small>{/if}
      </article>
      <div class="metric-row metric-row-values"><article class="metric"><p>Net value if sold today</p><strong>{euro.format(result.netLiquidationValue)}</strong><small>After estimated final TOB and applicable tax</small></article><article class="metric"><p>Gross CSH2 value</p><strong>{euro.format(result.grossValue)}</strong><small>{number.format(result.units)} CSH2 units{result.availableCash ? ` · ${euro.format(result.availableCash)} cash` : ''}</small></article></div>
      <div class="metric-row metric-row-details"><article class="metric"><p>Taxes already paid</p><strong>{euro.format(result.paidTob + result.paidCgt + result.paidReyndersTax)}</strong><small>TOB {euro.format(result.paidTob)} · {settings.applyReyndersTax ? `Reynders Tax ${euro.format(result.paidReyndersTax)}` : `CGT ${euro.format(result.paidCgt)}`}</small></article><article class="metric"><p>Taxes if sold today</p><strong>{euro.format(result.terminalTob + result.terminalCgt + result.terminalReyndersTax)}</strong><small>TOB {euro.format(result.terminalTob)} · {settings.applyReyndersTax ? `Reynders Tax ${euro.format(result.terminalReyndersTax)}` : `CGT ${euro.format(result.terminalCgt)}`}</small></article><article class="metric"><p>Broker fees</p><strong>{euro.format(result.paidBrokerFees + result.terminalBrokerFee)}</strong><small>Paid {euro.format(result.paidBrokerFees)} · if sold today {euro.format(result.terminalBrokerFee)}</small></article></div>
      {#if result.interestPayoutAssessment}{@const assessment = result.interestPayoutAssessment}<article class="metric"><p>Interest payout timing</p><strong>{assessment.preferred === 'either' ? 'The projected values are effectively the same.' : `${assessment.preferred === 'move now' ? 'Moving now' : `Waiting until ${date.format(new Date(`${assessment.payoutDate}T00:00:00Z`))}`} is projected to be ${euro.format(Math.abs(assessment.difference))} better.`}</strong><small>Projected net value on {date.format(new Date(`${assessment.payoutDate}T00:00:00Z`))}: move now {euro.format(assessment.immediateValue)} · wait {euro.format(assessment.waitingValue)}. Assumes CSH2 keeps its {assessment.trendDays}-day trend ({percent(assessment.trendReturnPercent)}%).</small></article>{/if}
    </div>
    <section class="panel chart-panel" aria-labelledby="return-heading"><div class="section-title"><div><p class="eyebrow">After transaction costs and applicable tax</p><h3 id="return-heading">Cumulative backtest return</h3></div></div><p class="chart-key"><span class="chart-key-csh2">CSH2 backtest</span><span class="chart-key-estr">Euro overnight benchmark portfolio</span><span class="chart-key-account">Your account</span>{#if controller.view.returnSeries.projected}<span class="chart-key-projected">Projection</span>{/if}</p>{#if controller.view.returnSeries.projected}{@const projection = controller.view.returnSeries.projected}<p class="chart-explanation projection-explanation">Dashed through {date.format(new Date(`${projection.payoutDate}T00:00:00Z`))}: assumes no further cash flows, CSH2 keeps its {projection.trendDays}-day trend ({percent(projection.trendReturnPercent)}%), the overnight rate remains {percent(projection.overnightRatePercent)}%, and the entered interest is paid as specified.</p>{/if}{#if controller.view.returnSeries.csh2.length || controller.view.returnSeries.overnight.length || controller.view.returnSeries.account.length}<LineChart data={controller.view.returnSeries} ariaLabel="Cumulative return of your account compared with CSH2 and a euro overnight benchmark portfolio using the same external cash flows" />{:else}<p class="chart-empty">There isn’t enough history yet to plot the cumulative backtest return.</p>{/if}</section>
{/if}
    <section class="panel chart-panel" aria-labelledby="benchmark-heading">
      <div class="section-title"><div class="benchmark-title"><p class="eyebrow">Underlying benchmark</p><h3 id="benchmark-heading">{controller.direction === 'forward' ? 'Forward' : 'Backward'} annualized returns · {periods[period].label}</h3></div>
        <div class="benchmark-control"><div class="benchmark-mode-picker" role="group" aria-label="Return direction"><button type="button" aria-pressed={controller.direction === 'backward'} onclick={() => controller.setDirection('backward')}>Backward</button><button type="button" aria-pressed={controller.direction === 'forward'} onclick={() => controller.setDirection('forward')}>Forward</button></div><div class="benchmark-period-picker" role="group" aria-label={`${controller.direction === 'forward' ? 'Forward' : 'Backward'} comparison period`}>{#each (controller.direction === 'backward' ? ['1m','3m','6m','1y','2y','5y'] : ['1m','3m','6m','1y']) as value}<button type="button" aria-pressed={period === value} onclick={() => controller.setPeriod(value as '1y')}>{periods[value as keyof typeof periods].label}</button>{/each}</div><div class="benchmark-tax-picker" role="group" aria-label="Tax treatment"><button type="button" aria-pressed={!controller.benchmarkAfterTax} onclick={() => controller.setBenchmarkAfterTax(false)}>Gross</button><button type="button" aria-pressed={controller.benchmarkAfterTax} onclick={() => controller.setBenchmarkAfterTax(true)}>After tax</button></div></div>
      </div>
      <p class="chart-key"><span class="chart-key-csh2">CSH2</span><span class="chart-key-estr">Euro overnight benchmark</span></p>
      <p class="chart-explanation benchmark-explanation">{controller.direction === 'forward' ? `Each point shows how CSH2 and the euro overnight benchmark performed over the following ${periods[period].description}. Use the date to compare a savings-account rate available then with what actually followed.` : `Each point compares its value with the value ${periods[period].description} earlier and annualizes the return.`}</p>
      {#if controller.benchmarkAfterTax}<p class="chart-explanation tax-explanation">CSH2 includes buy and sell TOB plus {benchmarkUsesReyndersTax ? '30% Reynders Tax' : '10% CGT from 2026'}, ignoring the annual CGT exemption. The euro overnight benchmark is unchanged.</p>{/if}
      {#if selectedSeries}<LineChart data={selectedSeries} from={controller.view?.from} to={controller.view?.to} ariaLabel={`${controller.direction === 'forward' ? 'Forward' : 'Backward'} annualized CSH2 return compared with the Euro overnight benchmark over ${periods[period].description}`} />{:else}<p class="chart-loading">{controller.benchmarkStatus.message || 'Preparing benchmark history…'}</p>{/if}
    </section>
{#if controller.view}
    {@const result = controller.view.result}
    {@const settings = controller.view.settings}
    <section class="panel ledger"><h3>Transaction ledger</h3><div class="table-wrap"><table><thead><tr><th>Date</th><th>Type</th><th>Amount</th><th>Price used</th><th>Units</th><th>Cash remaining</th><th>Broker fee</th><th>TOB</th>{#if !settings.applyReyndersTax}<th>CGT</th>{/if}{#if settings.applyReyndersTax}<th>Reynders Tax</th>{/if}{#if settings.applyCapitalGainsExemption && !settings.applyReyndersTax}<th>Exonerated CGT</th>{/if}</tr></thead><tbody>{#each result.entries as entry}<tr><td>{entry.date}</td><td>{entry.interestPayment ? 'Interest payment' : entry.type === 'inflow' ? 'Inflow / buy' : 'Outflow / sell'}</td><td>{euro.format(entry.amount)}</td><td>{entry.price === undefined ? '—' : euro.format(entry.price)}{entry.priceKind && entry.priceKind !== 'close' ? ` (${entry.priceKind})` : ''}</td><td>{entry.interestPayment ? '—' : number.format(entry.units)}</td><td>{euro.format(entry.remainingCash)}</td><td>{euro.format(entry.brokerFee)}</td><td>{euro.format(entry.tob)}</td>{#if !settings.applyReyndersTax}<td>{entry.cgt ? euro.format(entry.cgt) : '—'}</td>{/if}{#if settings.applyReyndersTax}<td>{entry.reyndersTax ? euro.format(entry.reyndersTax) : '—'}</td>{/if}{#if settings.applyCapitalGainsExemption && !settings.applyReyndersTax}<td>{entry.exoneratedCgt ? euro.format(entry.exoneratedCgt) : '—'}</td>{/if}</tr>{/each}</tbody></table></div></section>
{/if}
</section>
